package com.aether.evaluation.service.impl;
import com.aether.evaluation.entity.EvaluationTask; import com.aether.evaluation.entity.EvaluationResult; import com.aether.evaluation.entity.EvaluationCaseVersion; import com.aether.evaluation.entity.EvaluationExperiment; import com.aether.evaluation.service.EvaluationTaskService; import com.aether.evaluation.service.EvaluationTargetAdapter; import com.aether.evaluation.service.EvaluationResultService; import com.aether.evaluation.service.EvaluationCaseVersionService; import com.aether.evaluation.service.EvaluationExperimentService; import com.aether.evaluation.service.EvaluationWorkerSlotService; import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.alibaba.fastjson2.JSONObject; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.beans.factory.annotation.Autowired; import java.util.UUID; import java.util.List; import org.slf4j.Logger; import org.slf4j.LoggerFactory;
/** Claims durable tasks; execution handlers can consume CLAIMED tasks without holding a DB transaction. */
@Component public class EvaluationTaskWorker {
 private static final Logger log=LoggerFactory.getLogger(EvaluationTaskWorker.class); private final EvaluationTaskService service; private final EvaluationResultService resultService; private final EvaluationCaseVersionService caseVersionService; private final EvaluationGradingService gradingService; private final EvaluationExperimentAggregationService aggregationService; private final EvaluationExperimentService experimentService; private final EvaluationWorkerSlotService workerSlotService; private final String workerId=UUID.randomUUID().toString();
 @Autowired(required=false) private List<EvaluationTargetAdapter> adapters;
 public EvaluationTaskWorker(EvaluationTaskService service, EvaluationResultService resultService, EvaluationCaseVersionService caseVersionService, EvaluationGradingService gradingService, EvaluationExperimentAggregationService aggregationService, EvaluationExperimentService experimentService, EvaluationWorkerSlotService workerSlotService){this.service=service;this.resultService=resultService;this.caseVersionService=caseVersionService;this.gradingService=gradingService;this.aggregationService=aggregationService;this.experimentService=experimentService;this.workerSlotService=workerSlotService;}
 @Scheduled(fixedDelayString="${aether.evaluation.scan-interval-ms:3000}", initialDelay=10000)
 public void claimOne(){ recoverExpiredClaims(); expireTimedOut(); for(int i=0;i<10;i++){ EvaluationTask task=service.claim(workerId,60000L); if(task==null)return; if(!claimCapacity(task)){release(task);return;} try { if("GRADE".equals(task.getPhase())) { grade(task); continue; } EvaluationResult result=resultService.getById(task.getResultId()); if(result==null||"CANCELLED".equals(result.getExecutionStatus())){ finish(task); releaseCapacity(task); continue; } EvaluationExperiment experiment=experimentService.getById(result.getExperimentId()); if(experiment==null||"CANCELLED".equals(experiment.getStatus())){ finish(task); releaseCapacity(task); continue; } if(!canDispatch(result.getExperimentId(), experiment)){ release(task); releaseCapacity(task); return; } EvaluationTargetAdapter adapter=findAdapter(task); if(adapter==null){ failDispatch(task,"SNAPSHOT_EXECUTION_UNSUPPORTED"); continue; } if("QUEUED".equals(experiment.getStatus())){experiment.setStatus("RUNNING");experiment.setStartedAt(System.currentTimeMillis());experimentService.updateById(experiment);} task.setDispatchState("SENDING");service.updateById(task); adapter.dispatch(task); task.setDispatchState("ACKNOWLEDGED");finish(task); } catch(EvaluationPreDispatchException ex){ log.info("Evaluation task validation failed before dispatch: taskId={}, resultId={}, errorCode={}",task.getId(),task.getResultId(),ex.getErrorCode()); failDispatch(task,ex.getErrorCode()); } catch(RuntimeException ex){ log.error("Evaluation task dispatch failed: taskId={}, phase={}, targetType={}, resultId={}, dispatchState={}",task.getId(),task.getPhase(),task.getTargetType(),task.getResultId(),task.getDispatchState(),ex); if("SENDING".equals(task.getDispatchState())) unknownDispatch(task,"EXECUTION_UNKNOWN"); else failDispatch(task,"DISPATCH_FAILED"); } } }
 /**
  * A crashed worker leaves a task CLAIMED.  Safe pre-dispatch claims may be retried;
  * a claim that had begun an external send is deliberately made UNKNOWN instead of
  * being replayed, because replay could execute an Agent or workflow twice.
  */
 private void recoverExpiredClaims(){
  long now=System.currentTimeMillis();
  List<EvaluationTask> expired=service.list(Wrappers.lambdaQuery(EvaluationTask.class).eq(EvaluationTask::getStatus,"CLAIMED").lt(EvaluationTask::getLeaseUntil,now).eq(EvaluationTask::getDeleted,false));
  for(EvaluationTask task:expired){
   if("SENDING".equals(task.getDispatchState())){unknownDispatch(task,"EXECUTION_UNKNOWN");continue;}
   task.setStatus("READY");task.setLeaseOwner(null);task.setLeaseToken(null);task.setLeaseUntil(null);task.setNextRunAt(now);service.updateById(task);releaseCapacity(task);
  }
 }
 private boolean claimCapacity(EvaluationTask task){long now=System.currentTimeMillis();long leaseUntil=task.getDeadlineAt()==null?now+300000L:Math.max(task.getDeadlineAt()+60000L,now+300000L);return workerSlotService.claim(task.getPhase(),task.getId(),leaseUntil-now)!=null;}
 private void releaseCapacity(EvaluationTask task){workerSlotService.releaseByTask(task.getId());}
 private void grade(EvaluationTask task){ try { EvaluationResult result=resultService.getById(task.getResultId()); if(result==null){task.setStatus("FAILED");task.setErrorCode("RESULT_NOT_FOUND");service.updateById(task);return;} EvaluationCaseVersion item=caseVersionService.getById(result.getCaseVersionId()); if(item==null){task.setStatus("FAILED");task.setErrorCode("CASE_VERSION_NOT_FOUND");service.updateById(task);return;} gradingService.grade(result,item); task.setStatus("DONE");task.setLeaseOwner(null);task.setLeaseToken(null);task.setLeaseUntil(null);service.updateById(task); EvaluationResult refreshed=resultService.getById(result.getId()); if(refreshed!=null) aggregationService.refresh(findExperimentId(refreshed)); } finally { releaseCapacity(task); } }
 private String findExperimentId(EvaluationResult result){ return result.getExperimentId(); }
 private EvaluationTargetAdapter findAdapter(EvaluationTask task){ if(adapters==null)return null; return adapters.stream().filter(a->a.supports(task)).findFirst().orElse(null); }
 private void finish(EvaluationTask task){task.setStatus("DONE");task.setLeaseOwner(null);task.setLeaseToken(null);task.setLeaseUntil(null);service.updateById(task);}
 private void release(EvaluationTask task){task.setStatus("READY");task.setLeaseOwner(null);task.setLeaseToken(null);task.setLeaseUntil(null);task.setNextRunAt(System.currentTimeMillis()+1000L);service.updateById(task);}
 private boolean canDispatch(String experimentId, EvaluationExperiment experiment){int parallelism=2;try{JSONObject config=JSONObject.parseObject(experiment.getConfigJson());if(config!=null)parallelism=config.getIntValue("parallelism",2);}catch(RuntimeException ignored){}long running=resultService.count(Wrappers.lambdaQuery(EvaluationResult.class).eq(EvaluationResult::getExperimentId,experimentId).eq(EvaluationResult::getExecutionStatus,"RUNNING").eq(EvaluationResult::getDeleted,false));return running<parallelism;}
 private void expireTimedOut(){long now=System.currentTimeMillis();List<EvaluationTask> expired=service.list(Wrappers.lambdaQuery(EvaluationTask.class).eq(EvaluationTask::getPhase,"EXECUTE").eq(EvaluationTask::getStatus,"DONE").le(EvaluationTask::getDeadlineAt,now).eq(EvaluationTask::getDeleted,false));for(EvaluationTask task:expired){EvaluationResult result=resultService.getById(task.getResultId());if(result==null||!"RUNNING".equals(result.getExecutionStatus()))continue;EvaluationTargetAdapter adapter=findAdapter(task);if(adapter!=null){try{adapter.cancel(result.getId());}catch(RuntimeException ignored){}}result.setExecutionStatus("TIMED_OUT");result.setGradingStatus("SKIPPED");result.setQualityStatus("FAILED");result.setErrorCode("EVALUATION_TIMEOUT");resultService.updateById(result);releaseCapacity(task);aggregationService.refresh(result.getExperimentId());}}
 private void failDispatch(EvaluationTask task,String code){task.setStatus("FAILED");task.setErrorCode(code);task.setLeaseOwner(null);task.setLeaseToken(null);task.setLeaseUntil(null);service.updateById(task);releaseCapacity(task);EvaluationResult result=resultService.getById(task.getResultId());if(result!=null&&!"CANCELLED".equals(result.getExecutionStatus())){result.setExecutionStatus("FAILED");result.setGradingStatus("SKIPPED");result.setQualityStatus("FAILED");result.setErrorCode(code);resultService.updateById(result);aggregationService.refresh(result.getExperimentId());}}
 private void unknownDispatch(EvaluationTask task,String code){task.setStatus("DONE");task.setErrorCode(code);task.setLeaseOwner(null);task.setLeaseToken(null);task.setLeaseUntil(null);service.updateById(task);EvaluationResult result=resultService.getById(task.getResultId());if(result!=null&&!"CANCELLED".equals(result.getExecutionStatus())){result.setExecutionStatus("UNKNOWN");result.setGradingStatus("SKIPPED");result.setQualityStatus("INCOMPLETE");result.setErrorCode(code);resultService.updateById(result);aggregationService.refresh(result.getExperimentId());}}
}
